BEGIN;
CREATE TABLE pg13_support_replies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),ticket_id uuid NOT NULL REFERENCES pg13_support(id),actor_id uuid NOT NULL REFERENCES app_users(id),message text NOT NULL CHECK(length(message) BETWEEN 10 AND 4000),created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE pg13_support_replies ENABLE ROW LEVEL SECURITY;ALTER TABLE pg13_support_replies FORCE ROW LEVEL SECURITY;CREATE POLICY pg13_support_replies_owner ON pg13_support_replies TO CURRENT_USER USING(true) WITH CHECK(true);REVOKE ALL ON pg13_support_replies FROM PUBLIC,ekmivo_financial_runtime;
CREATE FUNCTION pg13_support_history(w uuid,a uuid,ticket uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE role text;BEGIN role:=pg13_actor(w,a,false);IF NOT EXISTS(SELECT 1 FROM pg13_support WHERE id=ticket AND workspace_id=w AND(actor_id=a OR role IN('owner','admin'))) THEN RAISE EXCEPTION 'support access denied' USING ERRCODE='42501';END IF;RETURN coalesce((SELECT jsonb_agg(jsonb_build_object('message',message,'created_at',created_at)) FROM pg13_support_replies WHERE ticket_id=ticket),'[]');END $$;
CREATE FUNCTION pg13_support_reply(a uuid,ticket uuid,msg text,target_status text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE t pg13_support;BEGIN
 IF NOT EXISTS(SELECT 1 FROM platform_administrators p JOIN app_users u ON u.id=p.user_id WHERE p.user_id=a AND u.disabled_at IS NULL) THEN RAISE EXCEPTION 'platform support required' USING ERRCODE='42501';END IF;
 IF length(btrim(msg)) NOT BETWEEN 10 AND 4000 OR target_status NOT IN('reviewing','resolved') THEN RAISE EXCEPTION 'invalid support reply' USING ERRCODE='22023';END IF;
 SELECT * INTO t FROM pg13_support WHERE id=ticket FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'ticket missing' USING ERRCODE='P0002';END IF;
 INSERT INTO pg13_support_replies(ticket_id,actor_id,message) VALUES(ticket,a,msg);UPDATE pg13_support SET status=target_status WHERE id=ticket;INSERT INTO pg13_control_audit(workspace_id,actor_id,action,resource_id) VALUES(t.workspace_id,a,'support-reply',ticket);RETURN jsonb_build_object('saved',true,'status',target_status);
END $$;
CREATE FUNCTION pg13_invite_resend(w uuid,a uuid,item uuid,cap text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE actor_role text;i pg13_invites;BEGIN actor_role:=pg13_actor(w,a,true);PERFORM pg_advisory_xact_lock(hashtextextended('pg13:control:'||w::text,0));IF length(cap)<>64 OR pg13_capability_override(w,a,'members:manage') IS FALSE THEN RAISE EXCEPTION 'invite scope denied' USING ERRCODE='42501';END IF;
 SELECT * INTO i FROM pg13_invites WHERE workspace_id=w AND id=item AND revoked_at IS NULL AND accepted_at IS NULL FOR UPDATE;IF NOT FOUND OR(actor_role<>'owner' AND i.role='admin') THEN RAISE EXCEPTION 'pending invite access denied' USING ERRCODE='42501';END IF;
 UPDATE pg13_invites SET token_digest=cap,expires_at=now()+interval '7 days' WHERE id=i.id;INSERT INTO pg13_control_audit(workspace_id,actor_id,action,resource_id) VALUES(w,a,'invite-renewed',i.id);RETURN jsonb_build_object('id',i.id,'saved',true);
END $$;
DO $$ DECLARE d text;BEGIN d:=pg_get_functiondef('pg13_workspace_read(uuid,uuid,text)'::regprocedure);d:=replace(d,'jsonb_agg(to_jsonb(s))','jsonb_agg(to_jsonb(s)||jsonb_build_object(''replies'',pg13_support_history(w,a,s.id)))');EXECUTE d;END $$;
REVOKE ALL ON FUNCTION pg13_support_history(uuid,uuid,uuid),pg13_support_reply(uuid,uuid,text,text),pg13_invite_resend(uuid,uuid,uuid,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION pg13_support_reply(uuid,uuid,text,text),pg13_invite_resend(uuid,uuid,uuid,text) TO ekmivo_financial_runtime;
COMMIT;
